import React, { useState, useRef, useEffect } from 'react';

import { cn } from '@/utils/index';

interface Option {
  value: string;
  label: string;
}

interface CustomSelectProps {
  options: Option[];
  value: string | string[];
  onChange: (value: string | string[]) => void;
  placeholder?: string;
  size?: 'normal' | 'wide';
  multiSelect?: boolean;
  hasError?: boolean;
}

export const CustomSelect: React.FC<CustomSelectProps> = ({
  options,
  value,
  onChange,
  placeholder = 'Выберите опцию',
  size = 'normal',
  multiSelect = false,
  hasError = false
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const selectRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (selectRef.current && !selectRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  // Нормализуем value в массив для удобства работы
  const selectedValues = Array.isArray(value) ? value : (value ? [value] : []);
  const selectedOptions = options.filter(option => selectedValues.includes(option.value));

  const handleOptionClick = (optionValue: string) => {
    if (multiSelect) {
      const newValues = selectedValues.includes(optionValue)
        ? selectedValues.filter(v => v !== optionValue)
        : [...selectedValues, optionValue];
      onChange(newValues);
    } else {
      onChange(optionValue);
      setIsOpen(false);
    }
  };

  const removeTag = (optionValue: string) => {
    const newValues = selectedValues.filter(v => v !== optionValue);
    onChange(newValues);
  };

  return (
    <div className={cn('vk-custom-select', size === 'wide' && 'vk-custom-select--wide', hasError && 'vk-custom-select--error')} ref={selectRef}>
      <div
        className={cn('vk-custom-select__trigger', isOpen && 'vk-custom-select__trigger--open')}
        onClick={() => setIsOpen(!isOpen)}
      >
        {selectedOptions.length > 0 ? (
          multiSelect ? (
            <div className="vk-custom-select__tags">
              {selectedOptions.map(option => (
                <span key={option.value} className="vk-custom-select__tag">
                  {option.label}
                  <button
                    type="button"
                    className="vk-custom-select__tag-remove"
                    onClick={(e) => {
                      e.stopPropagation();
                      removeTag(option.value);
                    }}
                  >
                    ×
                  </button>
                </span>
              ))}
            </div>
          ) : (
            <span className="vk-custom-select__selected">{selectedOptions[0].label}</span>
          )
        ) : (
          <span className="vk-custom-select__placeholder">{placeholder}</span>
        )}
        <span className={cn('vk-custom-select__arrow', isOpen && 'vk-custom-select__arrow--open')}>▼</span>
      </div>

      {isOpen && (
        <div className="vk-custom-select__dropdown">
          {options.map(option => (
            <div
              key={option.value}
              className={cn('vk-custom-select__option', selectedValues.includes(option.value) && 'vk-custom-select__option--selected')}
              onClick={() => handleOptionClick(option.value)}
            >
              {option.label}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};
